BEGIN;
SELECT plan(27);
INSERT INTO auth.users(id,email) VALUES('99999999-0000-0000-0000-000000000001','boundary@test.local');
INSERT INTO public.users(id,email) VALUES('99999999-0000-0000-0000-000000000001','boundary@test.local');
INSERT INTO public.user_profiles(user_id) VALUES('99999999-0000-0000-0000-000000000001');
INSERT INTO public.career_goals(user_id,goal_text) VALUES('99999999-0000-0000-0000-000000000001','Boundary goal');
INSERT INTO public.conversations(id,user_id) VALUES('99999999-0000-0000-0000-000000000002','99999999-0000-0000-0000-000000000001');
INSERT INTO public.messages(id,conversation_id,user_id,role,content,expires_at) VALUES('99999999-0000-0000-0000-000000000003','99999999-0000-0000-0000-000000000002','99999999-0000-0000-0000-000000000001','user','Unsummarized expired parent',now()-interval '1 second');
INSERT INTO public.messages(id,conversation_id,user_id,role,content,reply_to_message_id) VALUES('99999999-0000-0000-0000-000000000004','99999999-0000-0000-0000-000000000002','99999999-0000-0000-0000-000000000001','assistant','Live reply','99999999-0000-0000-0000-000000000003');
INSERT INTO public.ai_requests(user_id,task,status,created_at) VALUES('99999999-0000-0000-0000-000000000001','mentor_chat','preparing',now()-interval '31 days');
SELECT lives_ok($$INSERT INTO public.ai_requests(user_id,task,input_payload) VALUES('99999999-0000-0000-0000-000000000001','mentor_chat',jsonb_build_object('x',repeat('a',32759)))$$,'32768-byte input accepted');
SELECT throws_ok($$INSERT INTO public.ai_requests(user_id,task,input_payload) VALUES('99999999-0000-0000-0000-000000000001','mentor_chat',jsonb_build_object('x',repeat('a',32760)))$$,'23514',NULL,'32769-byte input denied');
SELECT throws_ok($$INSERT INTO public.ai_requests(task,input_payload) VALUES('mentor_chat','[]')$$,'23514',NULL,'Input must be an object');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"99999999-0000-0000-0000-000000000001","role":"authenticated"}',true);
SELECT throws_ok($$SELECT input_payload FROM public.ai_requests$$,'42501',NULL,'Private queue input cannot be read by its client owner');
SELECT is((SELECT count(*)::int FROM public.career_goals),1,'Active account sees own goal');
RESET ROLE;
UPDATE public.feature_controls SET enabled=false WHERE feature_key='roadmap_generator';
SET LOCAL ROLE authenticated;
SELECT ok(NOT private.effective_feature_access('99999999-0000-0000-0000-000000000001','roadmap_generator'),'Global off denies generation');
SELECT is((SELECT count(*)::int FROM public.career_goals),1,'Feature off preserves existing goal read');
RESET ROLE;
UPDATE public.users SET status='suspended',suspended_at=now() WHERE id='99999999-0000-0000-0000-000000000001';
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*)::int FROM public.career_goals),0,'Suspended account loses goal read');
SELECT is((SELECT count(*)::int FROM public.user_profiles),0,'Suspended account loses profile read');
SELECT ok(NOT private.effective_feature_access('99999999-0000-0000-0000-000000000001','ai_mentor'),'Suspended account loses effective access');
RESET ROLE;
UPDATE public.users SET status='active',suspended_at=NULL WHERE id='99999999-0000-0000-0000-000000000001';
SELECT throws_ok($$UPDATE public.system_configurations SET config_value='1' WHERE config_key='quality.report_auto_hide_threshold'$$,'23514',NULL,'Report threshold below 2 rejected');
SELECT throws_ok($$UPDATE public.system_configurations SET config_value='1001' WHERE config_key='quality.report_auto_hide_threshold'$$,'23514',NULL,'Report threshold above 1000 rejected');
SELECT throws_ok($$UPDATE public.system_configurations SET config_value='2.5' WHERE config_key='quality.report_auto_hide_threshold'$$,'23514',NULL,'Fraction threshold rejected');
SELECT throws_ok($$UPDATE public.system_configurations SET config_value='"2"' WHERE config_key='quality.report_auto_hide_threshold'$$,'23514',NULL,'String threshold rejected');
SELECT lives_ok($$UPDATE public.system_configurations SET config_value='2' WHERE config_key='quality.report_auto_hide_threshold'$$,'Nondefault report threshold 2 accepted');
SELECT throws_ok($$UPDATE public.system_configurations SET config_value='91' WHERE config_key='retention.mentor_message_days'$$,'23514',NULL,'Retention above cap rejected');
SELECT throws_ok($$UPDATE public.system_configurations SET config_value='0' WHERE config_key='retention.mentor_message_days'$$,'23514',NULL,'Zero retention rejected');
SELECT throws_ok($$UPDATE public.system_configurations SET config_value='4' WHERE config_key='roadmap.max_active'$$,'23514',NULL,'Frozen product cap rejected');
SELECT lives_ok($$SELECT private.cleanup_expired_retention()$$,'Retention executes');
SELECT is((SELECT count(*)::int FROM public.messages WHERE id='99999999-0000-0000-0000-000000000003'),0,'Unsummarized expired parent deleted');
SELECT is((SELECT reply_to_message_id FROM public.messages WHERE id='99999999-0000-0000-0000-000000000004'),NULL::uuid,'Live reply survives with NULL parent');
SELECT is((SELECT count(*)::int FROM public.ai_requests WHERE status='preparing' AND user_id='99999999-0000-0000-0000-000000000001'),0,'Old unfinished request purged by creation time');
INSERT INTO public.account_deletion_requests(id,user_id,status) VALUES('99999999-0000-0000-0000-000000000005','99999999-0000-0000-0000-000000000001','in_progress');
CREATE FUNCTION pg_temp.inject_failure() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'injected cascade failure'; END$$;
CREATE TRIGGER foundation_injected_delete BEFORE DELETE ON public.user_profiles FOR EACH ROW EXECUTE FUNCTION pg_temp.inject_failure();
SELECT throws_ok($$DELETE FROM auth.users WHERE id='99999999-0000-0000-0000-000000000001'$$,'P0001','injected cascade failure','Injected child cascade failure aborts deletion');
SELECT is((SELECT count(*)::int FROM auth.users WHERE id='99999999-0000-0000-0000-000000000001'),1,'Auth identity restored after failure');
SELECT is((SELECT status FROM public.account_deletion_requests WHERE id='99999999-0000-0000-0000-000000000005'),'in_progress'::public.deletion_request_status,'Completion tombstone also rolled back');
SELECT is((SELECT count(*)::int FROM public.user_profiles WHERE user_id='99999999-0000-0000-0000-000000000001'),1,'Child profile restored after failure');
DROP TRIGGER foundation_injected_delete ON public.user_profiles;
DELETE FROM auth.users WHERE id='99999999-0000-0000-0000-000000000001';
SELECT is((SELECT status FROM public.account_deletion_requests WHERE id='99999999-0000-0000-0000-000000000005'),'completed'::public.deletion_request_status,'Successful deletion completes retained tombstone');
SELECT * FROM finish();
ROLLBACK;
